export async function apiHealth(baseUrl = import.meta.env.VITE_API_URL || '{{apiUrl}}') {
  const response = await fetch(baseUrl + '{{healthPath}}');
  if (!response.ok) throw new Error('API health check failed: ' + response.status);
  return response.headers.get('content-type')?.includes('json') ? response.json() : { ok: true };
}
